<?php require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/auth.php';if(!setting('external_auth')){unset($_SESSION['otp_challenge'],$_SESSION['otp_subject'],$_SESSION['otp_channel'],$_SESSION['oauth'],$_SESSION['oauth_next']);redirect(current_user()?'khach_hang/ho_so.php':'dang_nhap.php');}$verify=get('verify');$user=$verify?require_role(['KHACH_HANG','NHAN_VIEN','ADMIN']):null;
handle_form(function()use($verify,$user){throttle('otp-ip',$_SERVER['REMOTE_ADDR']??'local',10,900);$channel=post('channel');must(in_array($channel,['email','sms'],true),'Kênh xác thực không hợp lệ.');if($verify){$u=$user;$purpose=$channel==='sms'?'VERIFY_PHONE':'VERIFY_EMAIL';if($channel==='sms')must((bool)preg_match('/^\+[1-9][0-9]{8,14}$/D',$u['so_dien_thoai']),'Số điện thoại cần dạng quốc tế, ví dụ +849xxxxxxxx.');}
else{$identity=post('identity');$u=$channel==='sms'?db_one("SELECT * FROM tai_khoan WHERE sdt_dang_nhap=? AND sdt_xac_minh_luc IS NOT NULL AND quyen<>'ADMIN' AND trang_thai='HOAT_DONG'",[$identity]):db_one("SELECT * FROM tai_khoan WHERE email=? AND email_xac_minh_luc IS NOT NULL AND quyen<>'ADMIN' AND trang_thai='HOAT_DONG'",[$identity]);$purpose='LOGIN';}
$id=$u?send_otp($u,$purpose,$channel):uid('OTP');$_SESSION['otp_challenge']=$id;$_SESSION['otp_subject']=$u?($channel==='sms'?$u['so_dien_thoai']:$u['email']):'';$_SESSION['otp_channel']=$channel;flash('Nếu thông tin đã được xác minh và cấu hình gửi hoạt động, mã đã được gửi.');redirect('xac_thuc/kiem_tra_otp.php');
},'xac_thuc/gui_otp.php'.($verify?'?verify='.rawurlencode($verify):''));
page_start($verify?'Xác minh thông tin liên hệ':'Đăng nhập bằng mã OTP');echo '<div class="auth panel">';token_form();select_field('channel','Nhận mã qua',['email'=>'Email','sms'=>'SMS'],$verify==='sms'?'sms':'email',true);if(!$verify)field('identity','Email hoặc SĐT quốc tế đã xác minh','','text','required');else echo '<p>Mã gửi đến thông tin đã lưu trong hồ sơ của bạn.</p>';echo '<button>Gửi mã xác thực</button></form><p class="muted">OTP có hiệu lực 5 phút, tối đa 5 lần thử.</p></div>';page_end();
